// 읽기 캐시: ConcurrentHashMap + NOT_FOUND 센티넬 (Optional 박싱 제거, TinyLFU 북키핑 제거)
private val vertexByIdCache: ConcurrentHashMap<VertexKey, Any> = ConcurrentHashMap(128)
private val verticesByLabelCache: ConcurrentHashMap<LabelKey, List<GraphVertex>> = ConcurrentHashMap(128)
private val neighborsCache: ConcurrentHashMap<NeighborKey, List<GraphVertex>> = ConcurrentHashMap(128)
private val shortestPathCache: ConcurrentHashMap<PathKey, Any> = ConcurrentHashMap(128)
private val allPathsCache: ConcurrentHashMap<PathKey, List<GraphPath>> = ConcurrentHashMap(128)
private val edgesByLabelCache: ConcurrentHashMap<EdgeLabelKey, List<GraphEdge>> = ConcurrentHashMap(128)

override fun findVerticesByLabel(label: String, filter: Map<String, Any?>): List<GraphVertex> {
    val key = LabelKey(label, filter)
    return verticesByLabelCache.computeIfAbsent(key) { delegate.findVerticesByLabel(label, filter) }
}

override fun neighbors(startId: GraphElementId, options: NeighborOptions): List<GraphVertex> {
    val key = NeighborKey(startId, options)
    return neighborsCache.computeIfAbsent(key) { delegate.neighbors(startId, options) }
}

override fun allPaths(fromId: GraphElementId, toId: GraphElementId, options: PathOptions): List<GraphPath> {
    val key = PathKey(fromId, toId, options)
    return allPathsCache.computeIfAbsent(key) { delegate.allPaths(fromId, toId, options) }
}

override fun findEdgesByLabel(label: String, filter: Map<String, Any?>): List<GraphEdge> {
    val key = EdgeLabelKey(label, filter)
    return edgesByLabelCache.computeIfAbsent(key) { delegate.findEdgesByLabel(label, filter) }
}

